+func buildPreSelectedAgentSet(installedAgentNames []types.AgentName, detected []agent.Agent, hasInstalledHooks bool) map[types.AgentName]struct{} {
+	preSelectedSet := make(map[types.AgentName]struct{})
+	if hasInstalledHooks {
+		for _, name := range installedAgentNames {
+			preSelectedSet[name] = struct{}{}
+		}
+		return preSelectedSet
