+		// External agents can be globally discoverable from PATH and may report
+		// presence broadly, so don't preselect them during first-time setup.
+		if external.IsExternal(ag) {
+			continue
+		}
+		preSelectedSet[ag.Name()] = struct{}{}
+	}
+
+	return preSelectedSet
