    ;;
  are-hooks-installed)
    echo '{"installed": false}'
    ;;
  *)
    echo '{}'
    ;;
esac
`

	if err := os.WriteFile(filepath.Join(dir, "entire-agent-"+name), []byte(script), 0o755); err != nil {
		t.Fatalf("Failed to write external agent binary: %v", err)
	}
}

